"""GEO7 report enrichment and human renderer. Public HTTP checks are not AI citations."""
import collections,hashlib,html,json,re,base64
from urllib.parse import urlparse,urlunparse
from audit import AuditParser
def normalized(url):
 p=urlparse(url);return urlunparse((p.scheme.lower(),p.netloc.lower(),p.path.rstrip("/") or "/", "", "", ""))
def enrich(v,crawl):
 pages=v["pages"];lookup={normalized(p["url"]):p for p in pages};raw={normalized(p["url"]):p for p in crawl.get("raw",[]) if "text/html" in p.get("content_type","")}
 checks=[];reviews=[];fingerprints=collections.defaultdict(list)
 def check(id,label,predicate,detail,absence="review"):
  ok=sum(bool(predicate(p)) for p in pages)
  checks.append({"id":id,"name":label,"passed":ok,"tested":len(pages),"state":"pass" if ok==len(pages) and pages else absence,"detail":detail})
 check("http","HTTP 200",lambda p:p["status"]==200,"Tikai savākto publisko HTTP atbilžu statuss.","fix")
 check("index","Nav noindex",lambda p:not p["noindex"],"Meta un X-Robots-Tag. Tas nepierāda indeksāciju.","fix")
 check("title","Lapas title",lambda p:bool(p["title"]),"Pārbaudīta klātbūtne; atbilstību nodomam izvērtē cilvēks.")
 check("description","Meta apraksts",lambda p:bool(p["meta"].get("description")),"Apraksta klātbūtne, ne garantēts Google snippets.")
 check("h1","Viena H1",lambda p:p["h1_count"]==1,"Viena skaidra H1 HTTP HTML.")
 check("canonical","Atbilstošs canonical",lambda p:bool(p["canonical"]) and normalized(p["canonical"])==normalized(p["final_url"]),"Salīdzināts ar gala URL; kanonizācijas izvēli Google var veikt citādi.")
 check("language","Norādīta valoda",lambda p:bool(p["html_lang"]),"HTML lang deklarācija; nav automātisks tulkojuma kvalitātes vērtējums.")
 check("hreflang","Hreflang saites",lambda p:bool(p["hreflang"]),"Klātbūtne. Atgriezeniskās saites pārbaudītas tikai savāktajā paraugā.")
 eligible=[p for p in pages if p["hreflang"]]
 self_missing=[p for p in eligible if not any(h["lang"]==p["html_lang"] and normalized(h["url"])==normalized(p["url"]) for h in p["hreflang"])]
 checks.append({"id":"hreflang-self","name":"Hreflang pašas lapas atsauce","passed":len(eligible)-len(self_missing),"tested":len(eligible),"state":"review" if self_missing else ("pass" if eligible else "unknown"),"detail":"Tikai lapas, kas lieto HTML hreflang. Sitemap/HTTP alternatīvas šeit netiek validētas."})
 if self_missing:
  v["findings"].append({"id":"hreflang-self","priority":"P2","title":"Hreflang norāda uz citu lapu","evidence":[{"url":p["url"],"html_lang":p["html_lang"],"hreflang":p["hreflang"]} for p in self_missing],"action":"Salāgot valodu atsauces ar pareizo lapas nodomu: katrai variācijai jānorāda sevi un atbilstošās pārējās variācijas. Pārbaudīt atgriezeniskās atsauces.","owner":"Web developer"})
 check("schema-syntax","JSON-LD sintakse",lambda p:not p["jsonld_invalid"],"Var būt PASS arī lapai bez JSON-LD; rich-result eligibility nav pārbaudīta.")
 check("alt","Attēlu alt",lambda p:p["images_without_nonempty_alt"]==0,"Netukša alt klātbūtne; dekoratīvam attēlam tukšs alt var būt pareizs.")
 check("readable","HTTP teksts",lambda p:p["http_text_words"]>0,"HTML teksts ir pieejams bez mūsu JS render. Skaits ietver navigāciju/footer.")
 for p in pages:
  source=raw.get(normalized(p["url"]));body=source["body"] if source else ""
  parser=AuditParser(p["final_url"]);parser.feed(body);text=re.sub(r"\s+"," "," ".join(parser.text_parts)).strip()
  fp=hashlib.sha256(text.encode()).hexdigest() if text else None
  if fp:fingerprints[fp].append(p["url"])
  paragraphs=[]
  for fragment in re.findall(r"<p\b[^>]*>(.*?)</p>",body,re.I|re.S):
   pp=AuditParser(p["url"]);pp.feed(fragment);t=re.sub(r"\s+"," "," ".join(pp.text_parts)).strip()
   if len(t)>=70:paragraphs.append(t[:350])
   if len(paragraphs)==3:break
  h1=[h["text"] for h in p["headings"] if h["level"]==1]
  reciprocal=[]
  for target in p["hreflang"]:
   other=lookup.get(normalized(target["url"]))
   reciprocal.append({"language":target["lang"],"target":target["url"],"state":"not_sampled" if other is None else ("observed" if any(normalized(x["url"])==normalized(p["url"]) for x in other["hreflang"]) else "review")})
  flags=[]
  if p["status"]!=200 or p["noindex"]:flags.append("piekļuve / noindex")
  if not p["title"] or p["h1_count"]!=1 or not p["canonical"]:flags.append("lapas pamatinformācija")
  if p["jsonld_invalid"]:flags.append("JSON-LD sintakse")
  reviews.append({"url":p["url"],"title":p["title"],"description":p["meta"].get("description"),"h1":h1,"canonical":p["canonical"],"status":p["status"],"lang":p["html_lang"],"words_http":p["http_text_words"],"schema_types":p["schema_types"],"schema_blocks":p["jsonld_blocks"],"schema_errors":p["jsonld_invalid"],"images":p["images"],"nonempty_alt":p["images"]-p["images_without_nonempty_alt"],"internal_links":p["internal_links"],"external_links":p["external_links"],"hreflang":reciprocal,"paragraph_samples":paragraphs,"text_sha256":fp,"flags":flags})
 duplicates=[]
 for fp,urls in fingerprints.items():
  urls=list(dict.fromkeys(urls))
  if len({normalized(u) for u in urls})>1:
   duplicates.append({"urls":urls,"parsed_http_text_sha256":fp})
   v["findings"].append({"id":"http-duplicate-"+str(len(duplicates)),"priority":"P1","title":"Dažādi URL atdod vienādu HTTP tekstu","evidence":{"urls":urls,"parsed_http_text_sha256":fp,"h1":[{"url":u,"h1":next(x["h1"] for x in reviews if x["url"]==u)} for u in urls],"scope":"Parsed HTTP body text, not a hydrated browser comparison"},"action":"Pārbaudīt SSR/route izvēli; katram nodomam atdot pareizo lapas saturu. Pēc labojuma atkārtot HTTP un pārlūka pārbaudi.","owner":"Web developer"})
 homepage=lookup.get(normalized(crawl["site"]))
 if homepage and not homepage["schema_types"]:
  v["findings"].append({"id":"homepage-entity","priority":"P2","title":"Sākumlapā nav JSON-LD pārbaudītajā HTTP paraugā","evidence":{"homepage":homepage["url"],"homepage_schema_types":[],"pages_with_jsonld":sum(bool(p["schema_types"]) for p in pages),"article_pages":[p["url"] for p in pages if "Article" in p["schema_types"]]},"action":"Pārbaudīt paredzēto Organization/Person identitāti pret sākumlapas redzamajiem faktiem; sagatavot atbilstošu Organization/WebSite projektu. Nav īpašas Google AI schema prasības.","owner":"Web developer"})
 translation=[]
 for p in pages:
  if p["html_lang"]!="en":continue
  for h in p["hreflang"]:
   if h["lang"]!="lv":continue
   other=lookup.get(normalized(h["url"]))
   if other and p["http_text_words"]>=500 and other["http_text_words"]/p["http_text_words"]<.45:
    translation.append({"en_url":p["url"],"lv_url":other["url"],"en_http_words":p["http_text_words"],"lv_http_words":other["http_text_words"]})
 if translation:
  v["findings"].append({"id":"language-review","priority":"P2","title":"Valodu pāra saturu pārbaudīt manuāli","evidence":translation,"action":"Pārbaudīt, vai valodu lapām apzināti ir atšķirīgs saturs vai EN/LV route problēma. Vārdu skaitu attiecība pati par sevi nepierāda kļūdu.","owner":"Growth lead"})
 requested={normalized(u) for u in crawl.get("sitemap_urls",[])};sampled=set(lookup)
 v["coverage"]={"http_responses":len(pages),"unique_pages":len(sampled),"sitemap_urls":len(requested),"sampled_sitemap_urls":len(requested & sampled),"not_sampled":[u for u in crawl.get("sitemap_urls",[]) if normalized(u) not in sampled],"scope":"Bounded public HTTP sample; unsampled URLs are not failures"}
 v["diagnostics"]=checks;v["page_reviews"]=reviews;v["content_duplicates"]=duplicates
 v["content_summary"]={"schema_pages":sum(bool(p["schema_types"]) for p in pages),"article_pages":sum("Article" in p["schema_types"] for p in pages),"http_languages":dict(collections.Counter(p["html_lang"] for p in pages)),"translation_review":translation}
 v["robot_access"]=crawl.get("robot_advisory",{});v["crawl_observed_at"]=crawl.get("timestamp_riga")
 v["ai_visibility"]={"status":"not_measured","engines":["ChatGPT Search","Google AI Overviews / AI Mode","Perplexity","Gemini"],"answers_observed":None,"citation_share":None,"note":"Nav reālu atbilžu izlases. Pieejams prompt protokols/apkopotājs; crawler piekļuve vai chatgpt / paid nav citējums."}
 notes={
 "gsc-baseline":("Atjaunot mērījumu bāzi","Dotajā avotā nav atlasītā perioda veiktspējas rindu; piekļuvi un periodu pārbauda atsevišķi.","Tāds pats tirgus/periods; saglabāta GSC atbilde ar faktiskajiem datiem vai izskaidrota aizkave."),
 "organic-baseline":("Nodalīt organisko no reklāmām","GA4 avoti ir atsevišķi: Google organic "+str(v["analytics"]["google_organic_sessions"])+"; chatgpt / paid "+str(v["analytics"]["chatgpt_paid_sessions"])+". Nav citējumu mērījums.","Piesaistes tabula nodalīta pa avotiem; AI Search citējumi mērīti atsevišķi."),
 "qualification-measurement":("Sasaistīt notikumu ar sarunu","generate_lead/sign_up/fit_call/WhatsApp notikumi nav unikāli kvalificēti cilvēki.","Pārbaudāms ceļš: source/UTM → contact_id → saruna → kvalifikācijas rezultāts."),
 "keyword-intent":("Izvēlēties vienu atbilstošu nodomu","Dotā Keyword Planner izlase ir tirgus ievade; tirgu un valodu norāda avota argumenti.","Viena jautājumu/lapu karte; prioritātei ir auditorija, avots un izvēlētais CTA."),
 "performance-unknown":("Iegūt ātruma mērījumu","Dotais PageSpeed avots nedod novērotu mērījumu; pārbauda tā kļūdu un tvērumu.","Atsevišķi saglabāti Lighthouse lab dati un pieejamie CrUX field dati."),
 "homepage-entity":("Salāgot publisko uzņēmuma identitāti","Sākumlapas HTTP paraugā nav JSON-LD; atbilstošu marķējumu izvērtē pret redzamajiem faktiem.","Schema sintakse derīga, identitāte atbilst redzamajam saturam, nav izdomātu faktu."),
 "hreflang-self":("Salāgot lapas valodu atsauces","HTML alternate saites nav pašas lapas valodas atsauce.","Pareizās EN/LV lapas savstarpēji un uz sevi atsaucas; Google localized versions vadlīnijas."),
 "language-review":("Salāgot EN/LV saturu","Izteikta satura atšķirība ir review signāls, ne automātiska kļūda.","Pārbaudīts konkrētais valodu pāris un route pēc hidratācijas.")}
 for f in v["findings"]:
  if f["id"].startswith("page-"):
   path=urlparse(f["evidence"]["url"]).path or "/"
   f["title"]="Lapas pārbaude: "+path
   if "canonical missing" in f["evidence"].get("observed",[]):
    f["action"]="Izvērtēt pašas lapas canonical deklarāciju "+f["evidence"]["url"]+". Pirms labojuma pārbaudīt faktiskās dublikātu/valodu versijas; canonical neesamība nav garantēta indeksācijas kļūda."
  if f["id"].startswith("heading-order"):
   f["title"]="Virsrakstu hierarhija: "+urlparse(f["evidence"]["url"]).path
   f["action"]="Pārskatīt H2→H4 pāreju raksta atsevišķās sadaļās; izlīdzināt hierarhiju pēc nozīmes. Tas ir struktūras/pieejamības review, ne pierādīts ranga kritums."
  title,why,accept=notes.get(f["id"],("Salabot konkrēto lapu",f["title"],"Atkārtot skartās lapas pārbaudi un saglabāt pirms/pēc pierādījumu."))
  if f["id"].startswith("http-duplicate"):title,why,accept=("Pārbaudīt skarto lapu SSR saturu","Atšķirīgu nodomu URL atdod identisku parsētu HTTP tekstu.","Abiem URL ir pareiza H1 un atšķirīgs paredzētais saturs gan HTTP, gan pārlūka skatā.")
  f["business_reason"]=why;f["acceptance"]=accept;f["work_item"]=title
 v["findings"].sort(key=lambda f:(f["priority"],0 if f["id"].startswith("http-duplicate") else 1))
 v["report_sections"]=["Kopsavilkums","Tehniskās pārbaudes","Lapas","Saturs un identitāte","Piesaistes dati","AI redzamība","Darbu plāns","Avoti"]
 return v
def render_html(v,package):
 e=html.escape
 fonts=(package/"assets/fonts.css").read_text()
 fonts=re.sub(r"url\('([^']+)'\)",lambda m:"url('data:font/woff2;base64,"+base64.b64encode((package/"assets"/m[1]).read_bytes()).decode()+"')",fonts)
 logo="data:image/svg+xml;base64,"+base64.b64encode((package/"assets/logo-areteaios.svg").read_bytes()).decode()
 def tag(text,state="info"):return '<span class="tag '+state+'">'+e(str(text))+'</span>'
 def evidence(value):return '<details class="evidence"><summary>Pierādījums</summary><pre>'+e(json.dumps(value,ensure_ascii=False,indent=2))+'</pre></details>'
 def section(id,title,body,intro=""):return '<section id="'+id+'"><div class="section-title"><span>'+str(["summary","technical","pages","content","traffic","ai","actions","sources"].index(id)+1).zfill(2)+'</span><div><h2>'+e(title)+'</h2>'+('<p>'+e(intro)+'</p>' if intro else '')+'</div></div>'+body+'</section>'
 cov=v["coverage"];cs=v["content_summary"];analytics=v["analytics"];period=analytics["period"]
 stats=[(str(cov["unique_pages"]),"Unikālas lapas",str(cov["sampled_sitemap_urls"])+"/"+str(cov["sitemap_urls"])+" sitemap paraugs"),
 (str(sum(c["state"]=="pass" for c in v["diagnostics"]))+"/"+str(len(v["diagnostics"])),"Tehniskās pārbaudes","Bāzes HTML signāli"),
 (str(cs["schema_pages"]),"Lapas ar JSON-LD",str(cs["article_pages"])+" Article lapas"),
 ("Nav mērīts","AI atbildes","Citējumi un rekomendācijas")]
 findings=v["findings"]
 summary='<div class="metrics">'+''.join('<div><strong>'+e(a)+'</strong><b>'+e(b)+'</b><small>'+e(c)+'</small></div>' for a,b,c in stats)+'</div><div class="summary-grid"><article class="box"><h3>Kas darbojas</h3><ul><li>Publiskās lapas atbild un atdod lasāmu HTTP tekstu.</li><li>Title/H1 pārbaudīti katrai lapai; canonical un valodu izņēmumi uzskaitīti tabulā.</li><li>JSON-LD klātbūtne un Article lapas saskaitītas atsevišķi no sintakses pārbaudes.</li><li>GSC īpašuma piekļuve un GA4 datu lasījums darbojas.</li></ul></article><article class="box"><h3>Pirmā prioritāte</h3><p>'+e(findings[0]["title"] if findings else "Nav konkrēta secinājuma")+'</p><p>'+e(findings[0]["action"] if findings else "Pārbaudīt ievadi")+'</p><a href="#actions" class="button">Skatīt darbu plānu ↓</a></article></div>'
 tech='<div class="table-wrap"><table><thead><tr><th>Pārbaude</th><th>Rezultāts</th><th>Tvērums</th></tr></thead><tbody>'+''.join('<tr><td>'+e(c["name"])+'</td><td>'+tag(str(c["passed"])+"/"+str(c["tested"]),c["state"])+'</td><td>'+e(c["detail"])+'</td></tr>' for c in v["diagnostics"])+'</tbody></table></div><div class="two-col"><article class="box"><h3>Robots piekļuve</h3>'+''.join('<div class="data-row"><span>'+e(k)+'</span>'+tag("Atļauts HTTP noteikumos" if val else "Nav atļauts / nav zināms","pass" if val else "review")+'</div>' for k,val in v["robot_access"].items())+'<p class="note">robots.txt padomdevēja pārbaude; nav CDN, bot verifikācijas vai indeksācijas tests. GPTBot/ClaudeBot training piekļuve nav AI Search obligāta prasība.</p></article><article class="box"><h3>Vēl nepārbaudīts</h3><ul><li>Pārlūka render / hidratācija.</li><li>Rich result eligibility un ārējs schema validator.</li><li>Lighthouse / CrUX: izmanto tikai dotajā avotā faktiski novērotus datus.</li><li>Indeksācijas statuss un reālu AI atbilžu izlase.</li></ul><details><summary>Sitemap URL ārpus parauga ('+str(len(cov["not_sampled"]))+')</summary><ul>'+''.join('<li>'+e(x)+'</li>' for x in cov["not_sampled"])+'</ul></details></article></div>'
 pages='<label class="search">Meklēt lapu <input id="page-search" type="search" placeholder="URL, virsraksts vai valoda…" aria-label="Filtrēt lapu tabulu"></label><div class="table-wrap"><table id="page-table"><thead><tr><th>Lapa / H1</th><th>HTTP</th><th>Valoda</th><th>Vārdi*</th><th>JSON-LD</th><th>Detaļas</th></tr></thead><tbody>'
 for p in v["page_reviews"]:
  short=urlparse(p["url"]).path or "/"
  detail={"title":p["title"],"description":p["description"],"canonical":p["canonical"],"hreflang":p["hreflang"],"images":p["images"],"nonempty_alt":p["nonempty_alt"],"internal_links":p["internal_links"],"external_links":p["external_links"],"schema_types":p["schema_types"],"schema_errors":p["schema_errors"],"text_sha256":p["text_sha256"]}
  pages+='<tr data-page-row data-filter="'+e((p["url"]+" "+p["title"]+" "+p["lang"]).lower(),quote=True)+'"><td><a href="'+e(p["url"])+'" target="_blank" rel="noopener noreferrer">'+e(short)+'</a><small>'+e(" · ".join(p["h1"]))+'</small></td><td>'+tag(p["status"],"pass" if p["status"]==200 else "fix")+'</td><td>'+e(p["lang"])+'</td><td>'+str(p["words_http"])+'</td><td>'+e(", ".join(p["schema_types"]) or "Nav")+'</td><td>'+evidence(detail)+'</td></tr>'
 pages+='</tbody></table></div><p class="note">* HTTP vārdu skaits ietver navigāciju/footer. Nav satura kvalitātes vērtējums. Attēla alt, schema un hreflang statuss ir izvēršams katrai lapai.</p>'
 duplicates='<div class="two-col"><article class="box"><h3>HTTP satura dublikāti</h3>'+(''.join('<p>'+e(" ↔ ".join(d["urls"]))+'</p>'+evidence(d) for d in v["content_duplicates"]) or '<p>Dažādu URL vienāds parsētais teksts paraugā nav atrasts.</p>')+'<p class="note">Hashes parāda identisku HTTP tekstu. JS render var atšķirties, tādēļ vajag arī hidratācijas pārbaudi.</p></article><article class="box"><h3>Uzņēmuma un autora identitāte</h3><p>'+str(cs["schema_pages"])+' lapās ir JSON-LD; '+str(cs["article_pages"])+' lapās Article. Sākumlapas marķējumu salāgo ar jau lietoto bloga identitāti.</p><p class="note">Schema nav garantēts citējums. Autoram, uzņēmumam un apgalvojumiem jāatbilst redzamajam saturam.</p>'+evidence({"languages":cs["http_languages"],"translation_review":cs["translation_review"]})+'</article></div><h3 class="subheading">Satura piemēri no HTTP atbildēm</h3><div class="sample-grid">'+''.join('<article class="box"><a href="'+e(p["url"])+'">'+e(urlparse(p["url"]).path or "/")+'</a><h3>'+e(" · ".join(p["h1"]))+'</h3>'+''.join('<blockquote>'+e(s)+'</blockquote>' for s in p["paragraph_samples"][:2])+'</article>' for p in v["page_reviews"][:3])+'</div>'
 channels=analytics["channels"];total=sum(r.get("sessions",0) or 0 for r in channels)
 traffic='<p class="period">GA4 periods: '+e(str(period.get("start_date"))+' — '+str(period.get("end_date")))+'. Dati nolasīti '+e(str(v.get("native_observed_at","nav norādīts")))+'.</p><div class="two-col"><article class="box"><h3>Piesaistes kanāli</h3>'+''.join('<div class="channel"><div><b>'+e(r["sessionSourceMedium"])+'</b><strong>'+str(int(r["sessions"]))+'</strong></div><div class="bar"><i style="width:'+str(round((r["sessions"]/total*100) if total else 0,2))+'%"></i></div><small>'+str(int(r.get("keyEvents",0)))+' keyEvents</small></div>' for r in channels)+'<p class="note">Atgriezto kanālu rindu summa '+str(int(total))+' sesijas. Nav unikālu cilvēku skaits; session_start ir atsevišķs notikuma mērījums.</p></article><article class="box"><h3>Kontaktēšanās notikumi</h3><div class="table-wrap"><table><thead><tr><th>Notikums</th><th>eventCount</th></tr></thead><tbody>'+''.join('<tr><td>'+e(r["eventName"])+'</td><td>'+str(int(r["eventCount"]))+'</td></tr>' for r in analytics["events"] if r["eventName"] in ["generate_lead","sign_up","fit_call_click","whatsapp_clicked"])+'</tbody></table></div><p>Šie notikumi vēl nepierāda kvalificētu uzņēmēju sarunu skaitu.</p><div class="pipeline"><span>Avots / UTM</span>→<span>Kontaktpersona</span>→<span>Saruna</span>→<span>Kvalificēts</span></div><p class="note">Jāpārbauda viena identificējama CRM ķēde, ne jāsaskaita atšķirīgi klikšķi.</p></article></div><article class="box"><h3>Search Console</h3><p>Search Console stāvokli rāda pievienotie avoti. Trūkstošs vai tukšs avots nepierāda nulles trafiku, piekļuvi vai indeksācijas statusu.</p>'+evidence({k:x for k,x in v["connectors"].items() if k.startswith("gsc-")})+'</article>'
 ai='<div class="box"><div class="ai-status">'+tag("Nav reālas AI atbilžu izlases","unknown")+'<p>'+e(v["ai_visibility"]["note"])+'</p></div><div class="table-wrap"><table><thead><tr><th>Meklēšanas produkts</th><th>Atbildes</th><th>Citējumi</th><th>Rekomendācijas</th></tr></thead><tbody>'+''.join('<tr><td>'+e(x)+'</td><td>Nav mērīts</td><td>—</td><td>—</td></tr>' for x in v["ai_visibility"]["engines"])+'</tbody></table></div><p class="note">Nākamais tests: vienādi auditorijas jautājumi, izvēlēts tirgus, reālas saglabātas atbildes, datums/modelis/run_id. Unknown/error nav 0%. Branded un unbranded jautājumus vērtē atsevišķi.</p></div>'
 keywords=v["keyword_ideas"]
 ai+='<article class="box"><h3>Atslēgvārdu sākuma atlase</h3><p class="note">UK / English · Keyword Planner pirmās20 idejas · avota nolasījums '+e(str(v.get("keyword_observed_at","nav norādīts")))+'; Ads competition nav SEO difficulty.</p><div class="table-wrap"><table><thead><tr><th>Atslēgvārds</th><th>Vid. mēneša meklējumi</th><th>Ads competition</th></tr></thead><tbody>'+''.join('<tr><td>'+e(k["keyword"])+'</td><td>'+str(k["average_monthly_searches"])+'</td><td>'+e(k["competition"])+'</td></tr>' for k in keywords if k["keyword"] in ["ai operating system","ai for business","business knowledge management","ai for small business","ai for business leaders"])+'</tbody></table></div></article>'
 actions=''.join('<article class="action box"><div class="action-head">'+tag(f["priority"],"fix" if f["priority"]=="P1" else "review")+'<h3>'+e(f["title"])+'</h3><span class="owner">'+e(f["owner"])+'</span></div><div class="action-grid"><div><small>Kāpēc tas jāņem vērā</small><p>'+e(f["business_reason"])+'</p></div><div><small>Konkrētā darbība</small><p>'+e(f["action"])+'</p></div><div><small>Pieņemšanas pārbaude</small><p>'+e(f["acceptance"])+'</p></div></div>'+evidence(f["evidence"])+'</article>' for f in findings)
 sources='<article class="box"><h3>Izpildes avoti</h3><div class="source-list">'+''.join('<a href="'+e(x.rsplit("/",1)[-1])+'">'+e(x.rsplit("/",1)[-1])+' ↗</a>' for x in v["source_files"])+'</div><p class="note">Crawl: '+e(str(v.get("crawl_observed_at")))+'. Reports: '+e(v["timestamp_riga"])+'. Autentifikācija nav iekļauta reportā. Avotu JSON ir lietotāja izvēlētās rezultātu mapes faili.</p><h3>Primārie metodikas avoti</h3><ul><li><a href="https://developers.google.com/search/docs/appearance/ai-features">Google AI features</a></li><li><a href="https://developers.google.com/search/docs/appearance/structured-data/sd-policies">Google structured data policies</a></li><li><a href="https://developers.google.com/search/docs/crawling-indexing/javascript/javascript-seo-basics">Google JavaScript SEO</a></li><li><a href="https://developers.google.com/search/docs/specialty/international/localized-versions">Google localized versions</a></li><li><a href="https://developers.google.com/search/docs/crawling-indexing/consolidate-duplicate-urls">Google canonical</a></li><li><a href="https://www.w3.org/WAI/tutorials/page-structure/headings/">W3C headings</a></li></ul><h3>Atlikumi</h3><ul>'+''.join('<li>'+e(x)+'</li>' for x in v["remaining"])+'</ul></article>'
 css=STYLE
 body=section("summary","Kopsavilkums",summary,"Novērotie dati, svarīgākais defekts un rezultāta mērījums.")+section("technical","Tehniskās pārbaudes",tech)+section("pages","Lapu pārbaudes",pages)+section("content","Saturs un identitāte",duplicates)+section("traffic","Piesaistes dati",traffic)+section("ai","AI redzamība un jautājumi",ai)+section("actions","Prioritātes un darbu plāns",actions)+section("sources","Avoti un tvērums",sources)
 nav=''.join('<a href="#'+id+'">'+name+'</a>' for id,name in zip(["summary","technical","pages","content","traffic","ai","actions","sources"],v["report_sections"]))
 script="document.getElementById('page-search').addEventListener('input',e=>{const q=e.target.value.toLocaleLowerCase();document.querySelectorAll('[data-page-row]').forEach(r=>r.hidden=!r.dataset.filter.includes(q));});document.getElementById('print').addEventListener('click',()=>window.print());"
 return '<!doctype html><html lang="lv"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>GEO7 SEO / GEO audits — '+e(v["site"])+'</title><style>'+fonts+css+'</style></head><body><header class="report-header"><div class="report-brand"><img src="'+logo+'" alt="Arete AIOS"><span>GEO7 / SEO + GEO AUDITS</span></div><button id="print" class="button">Drukāt / PDF</button></header><div class="report-shell"><aside><div class="nav-heading">Pārskats</div><nav>'+nav+'</nav><small>Growth lead / Growth<br>Evidence-based website review</small></aside><main><div class="report-hero"><span class="eyebrow">Vietnes audits</span><h1>'+e(urlparse(v["site"]).netloc)+'</h1><p>'+e(v["goal"])+'</p><div class="hero-meta"><span>'+e(v["timestamp_riga"])+'</span>'+tag(str(cov["unique_pages"])+'/'+str(cov["sitemap_urls"])+' sitemap URL paraugs','info')+'</div></div>'+body+'</main></div><script>'+script+'</script></body></html>'
