def markdown_detail(v):
 lines=["# GEO7 SEO/GEO audits — "+v["site"],"",v["timestamp_riga"],"",v["goal"],"",
 "## Tvērums",json.dumps(v["coverage"],ensure_ascii=False),"",
 "## Galvenās prioritātes"]
 for f in v["findings"]:
  lines.extend(["","### "+f["priority"]+" — "+f["title"],"Atbildīgais: "+f["owner"],"Kāpēc: "+f["business_reason"],"Darbība: "+f["action"],"Pieņemšana: "+f["acceptance"],"",json.dumps(f["evidence"],ensure_ascii=False,indent=2)])
 lines.extend(["","## Tehniskās pārbaudes","| Pārbaude | Rezultāts | Tvērums |","| --- | --- | --- |"])
 for c in v["diagnostics"]:lines.append("| "+c["name"]+" | "+str(c["passed"])+"/"+str(c["tested"])+" | "+c["detail"]+" |")
 lines.extend(["","## Lapas","| URL | H1 | Valoda | HTTP vārdi | JSON-LD |","| --- | --- | --- | --- | --- |"])
 for p in v["page_reviews"]:lines.append("| "+p["url"]+" | "+str(p["h1"]).replace("|","/")+" | "+p["lang"]+" | "+str(p["words_http"])+" | "+", ".join(p["schema_types"])+" |")
 lines.extend(["","## Piesaistes dati",json.dumps(v["analytics"],ensure_ascii=False,indent=2),"","## AI atbilžu mērījums",v["ai_visibility"]["note"],"","## Atlikumi",*["- "+x for x in v["remaining"]],"","## Avoti",*["- ["+x.rsplit("/",1)[-1]+"]("+x.rsplit("/",1)[-1]+")" for x in v["source_files"]]])
 return "\n".join(lines)+"\n"
